from collections import Counter
from scipy.optimize import minimize
from scipy.special import logsumexp, expit
rows=list(csv.DictReader(open('/scr/wurgaft/auto-psych/agent_trees/d82b8b9c1e886668/repo/_runs/cell_1/experiment2/model_loop/responses.csv')))
def coinc(ex):
    n=len(ex)
    if n<2: return 0.
    b=0.
    if len({e%2 for e in ex})==1: b=max(b,(n-1)*log(2))
    if all(e%5==0 for e in ex): b=max(b,(n-1)*log(5))
    if len({e%10 for e in ex})==1: b=max(b,(n-1)*log(10))
    return b/(3*log(10))
def fac(variant, ex, t, k):
    n=len(ex); g=reduce(gcd,ex); e=ex[k]
    if variant=='rule':
        return (0. if t%g==0 else 1.) if (n>1 and g>=2) else (1. if gcd(t,e)==1 else 0.)
    if variant=='inc':
        return 1. if (n>1 and g>=3 and t%g) else 0.
    if variant=='rule_s3':
        return (0. if t%g==0 else 1.) if (n>1 and g>=2) else ((1. if gcd(t,e)<3 else 0.) if n==1 else (1. if gcd(t,e)==1 else 0.))
    if variant=='inc_s3':
        if n==1: return 1. if gcd(t,e)<3 else 0.
        return 1. if (g>=3 and t%g) else 0.
    if variant=='inc_s3b':  # single: only when example has a factor>=3
        if n==1: return 1. if (e>=3 and e!=4 and e&(e-1)!=0 or e%3==0) and gcd(t,e)<3 else 0.
        return 1. if (g>=3 and t%g) else 0.
    if variant=='unified':
        return 1. if (g>=3 and gcd(t,g)<3) else 0.
    if variant=='inc_multfac':
        if n==1: return 0. if (t%e==0 or e%t==0) else 1.
        return 1. if (g>=3 and t%g) else 0.
    if variant=='rule_s3_g3':
        if n==1: return 1. if gcd(t,e)<3 else 0.
        if g>=3: return 0. if t%g==0 else 1.
        return 1. if gcd(t,e)==1 else 0.
