    N=len(rows); D=np.zeros((N,4)); U=np.ones((N,4)); P=np.ones((N,4)); F=np.zeros((N,4)); M=np.zeros((N,4),bool)
    sp=np.zeros(N); dh=np.zeros(N); ph=np.zeros(N); co=np.zeros(N); y=np.zeros(N)
    for i,r in enumerate(rows):
        ex=[int(x) for x in r['number_set'].split(',')][:4]; t=int(r['target']); n=len(ex)
