    lcm,lcu,st,ht,cp,cf,sh,a,b=th
    cp=abs(cp); cf=abs(cf); b=abs(b)
    g=np.exp(sh*co)[:,None]
    ls=g*(-np.exp(lcm-st*sp)[:,None]*D-np.exp(lcu+ht*dh)[:,None]*U-(cp*ph)[:,None]*P-cf*F)
