        r=minimize(nll,x0,args=(d,),method='Nelder-Mead',options={'maxiter':20000,'maxfev':20000,'xatol':1e-5,'fatol':1e-5})
        r=minimize(nll,r.x,args=(d,),method='BFGS')
        if best is None or r.fun<best.fun: best=r
    print(v, round(best.fun,2), np.round(best.x,2), flush=True)
